const groupName={checkout:'Shopping',shop:'Shopping',returns:'Shopping',food:'Food & Drink',transport:'Travel',travel:'Travel',booking:'Services',service:'Services',repair:'Services',health:'Healthcare',work:'Work',home:'Home',money:'Money',tech:'Technology',education:'Education',social:'Everyday',family:'Family',community:'Community'};
function categoryOf(t){
 if(!t.generated){let m={'Return clothing':'Shopping','Buy clothes':'Shopping','Buy a phone':'Shopping','Ask for directions':'Travel','Call for an appointment':'Healthcare','Check in at a hospital':'Healthcare','Order at a restaurant':'Food & Drink','Grocery shopping':'Shopping','At the pharmacy':'Healthcare','Order at a café':'Food & Drink','Job interview':'Work','At work':'Work','Take public transport':'Travel','Check in at a hotel':'Travel','At the airport':'Travel','At a bank':'Money','Repair a phone':'Technology','Meet someone new':'Everyday','Ask a teacher':'Education','Rent an apartment':'Home','Set up home internet':'Technology','Missing online delivery':'Services','At the dentist':'Healthcare','Meet a teacher':'Education','Change a work shift':'Work'};return m[t.title]||'Everyday'}
 if(t.group==='booking'){
  if(/dent|eye|checkup|clinic|health/.test(t.title.toLowerCase()))return 'Healthcare';
  if(/study room/.test(t.title.toLowerCase()))return 'Education';
  if(/restaurant|food/.test(t.title.toLowerCase()))return 'Food & Drink';
  return 'Services';
 }
 if(t.group==='service'){
  if(/library/.test(t.title.toLowerCase()))return 'Community';
  if(/self-checkout|store order/.test(t.title.toLowerCase()))return 'Shopping';
 }
 if(t.group==='repair'&&/phone|computer/.test(t.title.toLowerCase()))return 'Technology';
 if(t.group==='home'&&/rent/.test(t.title.toLowerCase()))return 'Home';
 return groupName[t.group]||'Services';
}
topicsAll.forEach((t,i)=>{t.category=categoryOf(t);t.index=i;});

